"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Jeder Raum: Haltbarkeit der Festung +{0} %. Passt zu „Verteidigung“: Tonwachen ×{1} verteidigen mit.",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Jeder Raum: Relikte auf Expeditionen +{0}. Passt zu „Verteidigung“: Waffen: Schaden +{1} %, Flächenschaden und Verlangsamung bei Treffer; andere: Wachen +{2}.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Jeder Raum: heimgebrachte Vorräte +{0} %. Passt zu „Glück“: Vorräte weitere +{1} %, Start-Punktemultiplikator +{2} pro Kampf.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Jeder Raum: Expeditionssicht +{0}, Start-Punktemultiplikator +{1}. Passt zu „Glück / Spezial“: Expeditionskarte von Anfang an aufgedeckt, Multiplikator weitere +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Jeder Raum: Expeditionstruppen-Angriff +{0} %. Passt zu „Training“: Expeditions-EP des Anführers +{1} %.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Jeder Raum: Expeditionstruppen-LP +{0} %. Passt zu „Medizin“: Krankenhausheilung +{1} %, Anführer heilt täglich weitere {2} %.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Jeder Raum: Bauplan-Droprate +{0} %. Passt zu „Sci-Fi“: Basis +{1} Seelensplitter pro Tag.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Jeder Raum: Bauplan-Droprate +{0} %. Passt zu „Schmieden“: {1} % Chance auf ein zusätzliches Relikt beim Schmieden.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Jeder Raum: Basis +{0} Seelensplitter pro Tag. Passt zu „Magie“: weitere +{1} pro Tag.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Jeder Raum: Basis +{0} Vorräte pro Tag. Passt zu „Logistik“: eigener Effekt dieses Raums ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Jeder Raum: Basis +{0} Vorräte pro Tag, Anführer erhält {1} EP pro Tag. Passt zu „Logistik / Natur“: eigener Effekt dieses Raums ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Jeder Raum: Relikt-Schmiedekosten -{0} %. Passt zu „Schmieden / Waffe“: Schmieden: {1} % Chance auf Qualität +{2}; Waffen: Schaden +{3} %.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Jeder Raum: Bauzeit halbiert, {0} % der Vorräte bei Fertigstellung erstattet. Passt zu „Weltwunder“: Erstattung steigt auf {1} %.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Jeder Raum: Schaden aller Verteidigungstürme +{0} %. Passt zu „Waffe“: Reichweite +{1}, Angriffstempo +{2} %.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Jeder Raum: Grabungskosten -{0} %. Passt zu „Spezial“: alle Bauten brauchen {1} T. weniger.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Jeder Raum: Start-Punktemultiplikator +{0} pro Kampf. Passt zu „Schmieden“: geschmiedete Relikte immer Qualität +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Jeder Raum: Abklingzeit der Anführer-Fähigkeit -{0} Station(en). Passt zu „Glück“: Hilfsgegenstände zum Expeditionsstart +{1} (Effekte mindestens „Episch“).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Jeder Raum: Anführer-Angriff +{0} %. Passt zu „Waffe“: Schaden +{1} %, jeder Angriff löst einen Kettenblitz aus ({2} Sprünge).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Jeder Raum: Dein Anführer heilt {0} % LP pro Tag (ohne Krankenhaus). Passt zu „Medizin / Wasser“: Krankenhausheilung +{1} %; Reichweite von Wasserwaffen +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Jeder Raum: Dein Anführer erhält {0} EP pro Tag. Passt zu „Produktion“: eigene Produktion dieses Raums ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Jeder Raum: Dein Anführer erhält {0} EP pro Tag. Passt zu „Training“: Expeditions-EP des Anführers +{1} %.",
"任何房间：领袖生命 +{0}%。契合「训练」：领袖攻击 +{1}%。": "Jeder Raum: Anführer-LP +{0} %. Passt zu „Training“: Anführer-Angriff +{1} %.",
