"前面是": "Voraus:",
"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Voraus: „Friedhof“. Dort ist der Nebel am dichtesten, und jede Nacht gibt es mehr frische Gräber.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Voraus: „Montagehalle“. Das Letzte, was die Fabrik baute, hat alle Arbeiter in sich eingeschlossen.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Voraus: „Operationssaal“. Der Direktor sagt, die Operation war ein Erfolg – der Patient ist nur noch nicht aufgewacht.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Voraus: „Meeresgrund“. Unter dem Hafen liegt noch eine Stadt, und ihr Tor ist ein Maul.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Voraus: „Baum des Wissens“. Er erinnert sich an alles, was je im Wald geschah, und will sich an nichts mehr erinnern.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Voraus: „Elfenkönigin“. Sie wartet seit dreihundert Jahren am Mondteich. Sie sagt, auf dich habe sie gewartet.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "Voraus: „Zirkuszelt“. Das Lachen darin hat nie aufgehört – nur Publikum gibt es keines mehr.",
