"每个区域的最终首领有一座自己的建筑，图纸只从它身上掉；建好后立着它的石像或铜像。": "Jeder Endboss einer Region hat ein eigenes Gebäude; nur er lässt den Bauplan fallen. Ist es gebaut, steht dort seine Statue aus Stein oder Bronze.",
