"每次出征，基地就过去 {0} 天，挖掘和建造也会推进。点击地面上的「传送门」，再来一局！每天夜里混沌来袭，出征带回来的部队会留下守城。": "Jede Expedition dauert in der Basis {0} T., auch Grabungen und Bauten gehen voran. Klicke auf das „Portal“ an der Oberfläche und los geht's! Jede Nacht kommt ein Chaos-Ansturm, und die heimgebrachten Truppen bleiben zur Verteidigung.",
"每次出征，基地就过去 {0} 天，挖掘和建造也跟着推进。点击地面上的「传送门」，再点升起的碑出发。每天夜里混沌来袭，出征带回来的部队会留下守城。": "Jede Expedition dauert in der Basis {0} T., Grabungen und Bauten gehen mit voran. Klicke auf das „Portal“ an der Oberfläche, dann auf die aufgestiegene Stele, um aufzubrechen. Jede Nacht kommt ein Chaos-Ansturm, und die heimgebrachten Truppen bleiben zur Verteidigung.",
